"use client";

import { createContext, useCallback, useContext, useEffect, useId, useLayoutEffect, useMemo, useRef, useState } from "react";
import type { MouseEvent, ReactNode, Ref } from "react";
import { FluidHoverHighlight, useFluidHover } from "../lib/fluid-hover";
import { MenuHighlight } from "../lib/menu-highlight";
import { SiliconLink } from "../lib/silicon-provider";
import { Badge } from "../badge/badge";
import styles from "./nav-list.module.css";

type Box = { top: number; height: number; danger: boolean; glide: boolean };
const ITEM = "[data-nav-item]";
const boxOf = (item: HTMLElement): Omit<Box, "glide"> => ({ top: item.offsetTop, height: item.offsetHeight, danger: false });

/** What NavList's onNavigate receives: the chosen row's href, or none for an action row. */
export interface NavChoice { href?: string }

/** Lets NavItem reach its list without prop drilling: the active marker's position, and reporting a choice. */
const NavContext = createContext<{ activeChanged: () => void; navigate: (choice: NavChoice) => void } | null>(null);

export interface NavListProps {
  /** Names the navigation for screen readers, such as "Main" or "Settings". */
  label: string;
  /** NavItem and NavSection elements, in order. */
  children: ReactNode;
  /** Placement only (width, margins, grid area); the rows' look comes from the component. */
  className?: string;
  /** The `<nav>` element. */
  ref?: Ref<HTMLElement>;
  /**
   * Called when any row is chosen (click, Enter or Space; link and action rows), before it navigates or acts. A notification,
   * such as closing a phone sheet: it cannot cancel. Locked rows and modified clicks (a new tab or window) do not call it.
   */
  onNavigate?: (choice: NavChoice) => void;
}

/**
 * A sidebar's list of destinations: a `<nav>` with a list of NavItem rows, optionally grouped by NavSection. The row nearest
 * the pointer is lit (fluid hover), and the current page's marker glides when the page changes.
 */
export function NavList({ label, children, className, ref, onNavigate }: NavListProps) {
  const root = useRef<HTMLElement | null>(null);
  const [active, setActive] = useState<Box | null>(null);
  // The row nearest the pointer is lit, gaps included, and a click in a gap follows the row (lib/fluid-hover).
  const hover = useFluidHover(root, { items: ITEM });
  // The latest handler, read at choice time, so a new function each render never changes the context.
  const navigateHandler = useRef(onNavigate);
  useEffect(() => { navigateHandler.current = onNavigate; });

  const setRoot = useCallback((node: HTMLElement | null) => {
    root.current = node;
    if (typeof ref === "function") return ref(node);
    if (ref) ref.current = node;
  }, [ref]);

  // The active marker follows the item with aria-current. It glides only when the page changes, never on first paint.
  const measureActive = useCallback(() => {
    const item = root.current?.querySelector<HTMLElement>(`${ITEM}[aria-current="page"]`);
    setActive(current => {
      if (!item) return null;
      const next = boxOf(item);
      return current && current.top === next.top && current.height === next.height ? current : { ...next, glide: current !== null };
    });
  }, []);
  useLayoutEffect(() => {
    measureActive();
    const node = root.current;
    if (!node || typeof ResizeObserver === "undefined") return;
    // A resize (a late font, a collapsing section) moves the marker at once; only a page change glides.
    const observer = new ResizeObserver(() => {
      const item = node.querySelector<HTMLElement>(`${ITEM}[aria-current="page"]`);
      setActive(current => {
        if (!item) return null;
        const next = boxOf(item);
        return current && current.top === next.top && current.height === next.height ? current : { ...next, glide: false };
      });
    });
    observer.observe(node);
    return () => observer.disconnect();
  }, [measureActive]);

  const context = useMemo(() => ({ activeChanged: measureActive, navigate: (choice: NavChoice) => navigateHandler.current?.(choice) }), [measureActive]);
  return (
    <NavContext.Provider value={context}>
      <nav ref={setRoot} aria-label={label} className={[styles.list, className].filter(Boolean).join(" ")} {...hover.handlers}>
        {/* The current page's marker paints over the hover fill, so hovering the current row never lightens it. */}
        <FluidHoverHighlight hover={hover} className={styles.highlight} />
        <MenuHighlight state={active} className={styles.active} />
        <ul className={styles.items}>{children}</ul>
      </nav>
    </NavContext.Provider>
  );
}

export interface NavSectionProps {
  /** The section's heading, such as "Workspace". */
  label: string;
  /** The section's NavItem rows. */
  children: ReactNode;
}

/** A labelled group of NavItem rows inside a NavList. */
export function NavSection({ label, children }: NavSectionProps) {
  const id = useId();
  return (
    <li className={styles.section}>
      <div id={id} className={styles.sectionLabel}>{label}</div>
      <ul className={styles.items} aria-labelledby={id}>{children}</ul>
    </li>
  );
}

interface NavItemBase {
  /** The row's label. */
  children: ReactNode;
  /** A 16px icon before the label. */
  icon?: ReactNode;
  /** The current page: sets aria-current="page" and the active marker. */
  active?: boolean;
  /** Turns the row off. It stays focusable (aria-disabled) so keyboard users can reach it and hear why. */
  disabled?: boolean;
  /** Why the row is off, such as "Pro". Shown as a badge and read as the row's description. Only shown when disabled. */
  reason?: string;
  /** Content at the row's end, such as a count or an avatar. Hidden while a reason shows. */
  trailing?: ReactNode;
  /**
   * Called each time the pointer enters the row or it receives focus, before it is chosen: start loading the destination
   * (prefetch). It can fire more than once, so keep it idempotent. Not called while disabled.
   */
  onIntent?: () => void;
  /** Placement only; the row's look comes from the component. */
  className?: string;
}

export type NavItemProps = NavItemBase & (
  | { /** A destination, rendered with the SiliconProvider's link. */ href: string; onSelect?: never }
  | { href?: never; /** An action, such as opening search. */ onSelect: () => void }
);

/** One row of a NavList: a link by `href`, or an action by `onSelect`. */
export function NavItem({ children, icon, active = false, disabled = false, reason, trailing, onIntent, className, href, onSelect }: NavItemProps) {
  const nav = useContext(NavContext);
  const reasonId = useId();
  const showReason = disabled && reason;
  useLayoutEffect(() => { nav?.activeChanged(); }, [active, nav]);

  const content = <>
    {icon ? <span className={styles.icon} aria-hidden="true">{icon}</span> : null}
    <span className={styles.label}>{children}</span>
    {/* Hidden from the name and read once, as the description (aria-describedby reads hidden text). */}
    {showReason ? <Badge id={reasonId} size="sm" className={styles.reason} aria-hidden="true">{reason}</Badge>
      : trailing ? <span className={styles.trailing}>{trailing}</span> : null}
  </>;
  const shared = {
    className: [styles.item, className].filter(Boolean).join(" "),
    "data-nav-item": "",
    "aria-current": active ? "page" as const : undefined,
    "aria-disabled": disabled || undefined,
    "aria-describedby": showReason ? reasonId : undefined,
  };

  if (disabled) {
    // No href and no action: it can be focused and read, but not followed.
    return <li><span {...shared} role={href ? "link" : "button"} tabIndex={0} onClick={(event: MouseEvent<HTMLElement>) => event.preventDefault()}>{content}</span></li>;
  }
  const intent = onIntent ? { onPointerEnter: onIntent, onFocus: onIntent } : {};
  if (href !== undefined) {
    // A modified click opens a new tab or window, so this page stays where it is: no choice to report.
    const onClick = (event: MouseEvent<HTMLAnchorElement>) => { if (event.button === 0 && !event.metaKey && !event.ctrlKey && !event.shiftKey && !event.altKey) nav?.navigate({ href }); };
    return <li><SiliconLink {...shared} {...intent} href={href} onClick={onClick}>{content}</SiliconLink></li>;
  }
  return <li><button {...shared} {...intent} type="button" onClick={() => { nav?.navigate({}); onSelect?.(); }}>{content}</button></li>;
}

export default NavList;

/* The list is the positioning box for both markers, so rows measure their offsetTop against it. Place it on --background or
   --surface; on a --surface-muted panel the hover fill has nothing to show against. */
.list { position: relative; display: block; font-family: var(--font-body); letter-spacing: var(--tracking-body); }
.items { display: grid; gap: var(--space-hair); margin: 0; padding: 0; list-style: none; }
.section + .section, .items > li + .section { margin-top: var(--space-group); }
.sectionLabel { padding: var(--space-tight) var(--space-related); color: var(--text-muted); font-size: var(--text-xs); font-weight: 500; line-height: var(--leading-body); }

/* Two markers under the rows: the current page (stronger), and the pointer's hover, which glides between rows. */
.active, .highlight { position: absolute; top: 0; right: 0; left: 0; border-radius: var(--radius-control); corner-shape: var(--corner-shape); pointer-events: none; }
.active { background: var(--surface-pressed); }
.highlight { background: var(--surface-muted); }

.item { position: relative; display: flex; box-sizing: border-box; width: 100%; min-height: 2rem; align-items: center; gap: var(--space-related); margin: 0; padding: 0 var(--space-related); border: 0; border-radius: var(--radius-control); corner-shape: var(--corner-shape); background: transparent; color: var(--text-secondary); font: inherit; font-size: var(--text-sm); line-height: var(--leading-body); text-align: left; text-decoration: none; cursor: pointer; -webkit-tap-highlight-color: transparent; transition: color var(--duration-fast) var(--ease-standard); }
.item:hover, .item:focus-visible, .item[aria-current="page"] { color: var(--foreground); }
.item[aria-current="page"] { font-weight: 500; }
.item[aria-disabled="true"] { color: var(--text-muted); cursor: not-allowed; }
.icon { display: inline-flex; flex: none; color: var(--text-secondary); }
.icon svg { width: 16px; height: 16px; }
.item[aria-current="page"] .icon, .item:hover .icon { color: var(--foreground); }
.item[aria-disabled="true"] .icon { color: var(--text-muted); }
.label { min-width: 0; flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.trailing { display: inline-flex; flex: none; align-items: center; color: var(--text-muted); font-size: var(--text-xs); font-variant-numeric: tabular-nums; }
.reason { flex: none; }

@media (prefers-reduced-motion: reduce) { .item { transition: none; } }

"use client";

import { useRef } from "react";
import type { FocusEvent, MouseEvent } from "react";
import { motion, useReducedMotion } from "motion/react";
import { FluidHoverHighlight, useFluidHover, type FluidRect } from "./fluid-hover";
import { motionTokens } from "./motion-tokens";

/** A fluid hover highlight in a menu: where it sits, whether it travels, its pointer session, and its tone. */
type FluidHighlight = { rect: FluidRect | null; glide: boolean; session: number; danger: boolean };
/** A marker positioned by top and height only (a list's current-page marker). */
type BarHighlight = { top: number; height: number; danger: boolean; glide: boolean };

const ITEMS = '[role="menuitem"], [role="menuitemcheckbox"], [role="menuitemradio"], [role="option"]';

/**
 * Fluid hover for a Radix menu or listbox (lib/fluid-hover): the item nearest the pointer is lit, gaps and padding
 * included, a click in a gap picks the lit item, and the keyboard moves the highlight with Radix's focus, without travel.
 * Spread `contentProps` on the content, call `reset` when it opens, and render `<MenuHighlight state={highlight} … />`
 * as its first child. Items mark a destructive tone with `data-tone="danger"`.
 */
export function useMenuHighlight(itemSelector = ITEMS) {
  // The content element is taken from its own events, so the hook never competes with the content's ref.
  const content = useRef<HTMLElement | null>(null);
  const hover = useFluidHover(content, { items: itemSelector });
  const own = (event: { currentTarget: EventTarget }) => { content.current = event.currentTarget as HTMLElement; };
  const { handlers } = hover;
  const highlight: FluidHighlight = { rect: hover.rect, glide: hover.glide, session: hover.session, danger: hover.item?.dataset.tone === "danger" };
  return {
    highlight,
    reset: hover.reset,
    contentProps: {
      onMouseEnter: (event: MouseEvent<HTMLElement>) => { own(event); handlers.onMouseEnter(); },
      onMouseMove: (event: MouseEvent<HTMLElement>) => { own(event); handlers.onMouseMove(event); },
      onMouseLeave: handlers.onMouseLeave,
      onKeyDownCapture: handlers.onKeyDownCapture,
      onFocus: (event: FocusEvent<HTMLElement>) => { own(event); handlers.onFocus(event); },
      onBlur: handlers.onBlur,
      onClick: (event: MouseEvent<HTMLElement>) => { own(event); handlers.onClick(event); },
    },
  };
}

/** The highlight itself: the fluid hover highlight, or a marker that moves by top and height (a current-page marker). */
export function MenuHighlight({ state, className }: { state: FluidHighlight | BarHighlight | null; className?: string }) {
  if (state && "session" in state) return <FluidHoverHighlight hover={state} className={className} tone={state.danger ? "danger" : undefined} />;
  return <BarMarker state={state} className={className} />;
}

function BarMarker({ state, className }: { state: BarHighlight | null; className?: string }) {
  const reduced = useReducedMotion();
  return <motion.span className={className} data-tone={state?.danger ? "danger" : undefined} aria-hidden="true" initial={false}
    animate={state ? { y: state.top, height: state.height, opacity: 1 } : { opacity: 0 }}
    transition={{ default: state?.glide && !reduced ? motionTokens.spring.fast : { duration: 0 }, opacity: { duration: reduced ? 0 : motionTokens.duration.fast } }} />;
}

"use client";

/**
 * Fluid hover: in a set of items (a menu, a list, tabs, a grid), the item nearest the pointer is lit, even while the
 * pointer is in a gap, the padding or past the last item, and one highlight springs between items. A click in a gap goes
 * to the lit item, so what is lit is what a click hits. A new pointer entry fades the highlight in where it lands instead
 * of sliding it over from the last item. The keyboard moves it without travel, and reduced motion keeps the fade but
 * drops the travel.
 *
 *   const list = useRef<HTMLUListElement>(null);
 *   const hover = useFluidHover(list, { items: "[data-item]" });
 *   <ul ref={list} className={styles.list} {...hover.handlers}>      // .list { position: relative }
 *     <FluidHoverHighlight hover={hover} className={styles.highlight} />
 *     …items…
 *   </ul>
 *
 * Adapted from Fluid Functionalism's use-fluid-hover and fluid-hover-highlight by Micka Touillaud (MIT),
 * https://github.com/mickadesign/fluid-functionalism. Items are found by a selector instead of registering themselves,
 * so a component adopts it without changing its items.
 */
import { useEffect, useEffectEvent, useRef, useState } from "react";
import type { FocusEvent, MouseEvent, PointerEvent, RefObject } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { motionTokens } from "./motion-tokens";

/** An item's box in the container's own layout space (unaffected by transforms or scrolling). */
export interface FluidRect { top: number; left: number; width: number; height: number }

export interface FluidHoverState {
  /** Where the highlight sits, or null when nothing is lit. */
  rect: FluidRect | null;
  /** The lit item. */
  item: HTMLElement | null;
  /** False when the highlight should jump (keyboard, a resize) rather than travel. */
  glide: boolean;
  /** Steps on each new pointer entry, so the highlight fades in where it lands. */
  session: number;
}

export interface FluidHoverOptions {
  /** Selector for the items inside the container. */
  items: string;
  /** "y" for lists (default), "x" for a row of tabs, "xy" for grids. */
  axis?: "x" | "y" | "xy";
  /** Items the highlight skips (and a gap click never activates). Defaults to disabled or aria-disabled items. */
  isItemDisabled?: (item: HTMLElement) => boolean;
  /** "skip" (default) lights the nearest enabled item even over a disabled one; "clear" lights nothing over a disabled item (a calendar's unavailable days). */
  disabled?: "skip" | "clear";
  /** Route a click in a gap to the lit item. On by default; turn it off where empty space should stay inert. */
  gapClick?: boolean;
  /** Light the item that receives keyboard focus. On by default. */
  followFocus?: boolean;
}

const defaultDisabled = (item: HTMLElement) =>
  item.matches(":disabled, [aria-disabled='true'], [data-disabled]");

/** Controls that sit between items keep their own clicks. */
const CONTROL = "input, textarea, select, button, a, summary, [contenteditable], [role='textbox'], [role='searchbox'], [role='button']";

/** The item's box relative to the container, summing offsets through positioned ancestors in between. */
export function rectOf(item: HTMLElement, container: HTMLElement): FluidRect {
  let top = item.offsetTop, left = item.offsetLeft;
  let parent = item.offsetParent as HTMLElement | null;
  while (parent && parent !== container && container.contains(parent)) {
    top += parent.offsetTop + parent.clientTop;
    left += parent.offsetLeft + parent.clientLeft;
    parent = parent.offsetParent as HTMLElement | null;
  }
  return { top, left, width: item.offsetWidth, height: item.offsetHeight };
}

/**
 * The item the pointer is inside, or else the one whose edge is nearest along the axis (both axes for a grid). Edges, not
 * centres, so a gap next to a wide item still lights the item the pointer is closer to.
 */
export function pickNearest(items: HTMLElement[], x: number, y: number, axis: "x" | "y" | "xy"): HTMLElement | null {
  let nearest: HTMLElement | null = null, best = Infinity;
  for (const item of items) {
    const r = item.getBoundingClientRect();
    if (!r.width && !r.height) continue;
    if (x >= r.left && x <= r.right && y >= r.top && y <= r.bottom) return item;
    const dx = Math.max(r.left - x, 0, x - r.right), dy = Math.max(r.top - y, 0, y - r.bottom);
    const distance = axis === "x" ? dx : axis === "y" ? dy : Math.hypot(dx, dy);
    if (distance < best) { best = distance; nearest = item; }
  }
  return nearest;
}

/** Hands a gap click to the item as a real mouse click (detail, modifiers and coordinates kept), so the item reads it as a pointer press, not a keyboard one. */
function forwardClick(item: HTMLElement, event: MouseEvent<HTMLElement>) {
  const { detail, clientX, clientY, screenX, screenY, ctrlKey, shiftKey, altKey, metaKey, button, buttons } = event;
  item.dispatchEvent(new globalThis.MouseEvent("click", { bubbles: true, cancelable: true, composed: true, view: window, detail, clientX, clientY, screenX, screenY, ctrlKey, shiftKey, altKey, metaKey, button, buttons }));
}

/** Whether an event happened inside the element whose handler hears it, not in a portalled child (a submenu, a tooltip). */
const isOwn = (event: { currentTarget: EventTarget; target: EventTarget }) =>
  !(event.currentTarget instanceof Node) || !(event.target instanceof Node) || event.currentTarget.contains(event.target);

export function useFluidHover<T extends HTMLElement>(container: RefObject<T | null>, options: FluidHoverOptions) {
  const { items: selector, axis = "y", isItemDisabled = defaultDisabled, disabled = "skip", gapClick = true, followFocus = true } = options;
  const [state, setState] = useState<FluidHoverState>({ rect: null, item: null, glide: false, session: 0 });
  const current = useRef(state);
  const pointer = useRef(false);
  const entering = useRef(false);
  const frame = useRef(0);

  function commit(next: FluidHoverState) {
    const prev = current.current;
    if (prev.item === next.item && prev.session === next.session && sameRect(prev.rect, next.rect)) return;
    current.current = next;
    setState(next);
  }

  function light(item: HTMLElement | null, glide: boolean) {
    const root = container.current;
    if (!root || !item) return commit({ ...current.current, rect: null, item: null, glide });
    let session = current.current.session;
    if (entering.current) { entering.current = false; session += 1; }
    commit({ rect: rectOf(item, root), item, glide: glide && session === current.current.session, session });
  }

  const enabledItems = () => {
    const root = container.current;
    return root ? [...root.querySelectorAll<HTMLElement>(selector)].filter(item => !isItemDisabled(item)) : [];
  };

  // The lit item can move under a still highlight (a resize, content above it changing): follow it without travel.
  const follow = useEffectEvent(() => { const { item } = current.current; if (item?.isConnected) light(item, false); });
  useEffect(() => {
    const root = container.current;
    if (!root || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(() => follow());
    observer.observe(root);
    return () => observer.disconnect();
  }, [container]);
  useEffect(() => () => cancelAnimationFrame(frame.current), []);

  const handlers = {
    onMouseEnter: () => { entering.current = true; },
    onMouseMove: (event: MouseEvent<T>) => {
      if (!isOwn(event)) return;
      pointer.current = true;
      const { clientX, clientY } = event;
      cancelAnimationFrame(frame.current);
      frame.current = requestAnimationFrame(() => {
        const over = disabled === "clear" ? document.elementFromPoint(clientX, clientY)?.closest<HTMLElement>(selector) : null;
        light(over && isItemDisabled(over) ? null : pickNearest(enabledItems(), clientX, clientY, axis), true);
      });
    },
    onMouseLeave: () => { cancelAnimationFrame(frame.current); entering.current = false; light(null, false); },
    onKeyDownCapture: () => { pointer.current = false; },
    onFocus: (event: FocusEvent<T>) => {
      if (!followFocus || pointer.current || !isOwn(event)) return;
      const item = event.target instanceof HTMLElement ? event.target.closest<HTMLElement>(selector) : null;
      if (item && container.current?.contains(item) && !isItemDisabled(item)) light(item, false);
    },
    onBlur: (event: FocusEvent<T>) => {
      if (!pointer.current && !event.currentTarget.contains(event.relatedTarget as Node | null)) light(null, false);
    },
    onClick: (event: MouseEvent<T>) => {
      if (!gapClick || !isOwn(event)) return;
      const target = event.target as Element;
      if (!target.isConnected || target.closest(selector) || target.closest(CONTROL)) return;
      const { item } = current.current;
      if (item?.isConnected && !isItemDisabled(item)) forwardClick(item, event);
    },
  };

  /** Clears the highlight at once, such as when a menu opens again. */
  const reset = () => { cancelAnimationFrame(frame.current); entering.current = true; light(null, false); };

  return { ...state, handlers, reset, light };
}

export interface NearestItemOptions extends Omit<FluidHoverOptions, "followFocus"> {
  /** Called with the nearest enabled item as the mouse moves over the container. */
  onPick: (item: HTMLElement) => void;
}

/**
 * Fluid hover's picking without its highlight, for a list that already keeps its own active item and highlight (a listbox
 * with aria-activedescendant, a roving list): the mouse picks the nearest enabled item, gaps and padding included, and a
 * click in a gap goes to that item. Spread the result on the container.
 */
// A hook only so callbacks that touch refs can be passed during render; it keeps no state.
export function useNearestItem<T extends HTMLElement>({ items: selector, axis = "y", isItemDisabled = defaultDisabled, gapClick = true, onPick }: NearestItemOptions) {
  const nearest = (event: MouseEvent<T>) => {
    if (!isOwn(event)) return null;
    const items = [...event.currentTarget.querySelectorAll<HTMLElement>(selector)].filter(item => !isItemDisabled(item));
    return pickNearest(items, event.clientX, event.clientY, axis);
  };
  return {
    onPointerMove: (event: PointerEvent<T>) => { if (event.pointerType !== "mouse") return; const item = nearest(event); if (item) onPick(item); },
    onClick: (event: MouseEvent<T>) => {
      if (!gapClick) return;
      const target = event.target as Element;
      if (!target.isConnected || target.closest(selector) || target.closest(CONTROL)) return;
      const item = nearest(event);
      if (item) forwardClick(item, event);
    },
  };
}

const sameRect = (a: FluidRect | null, b: FluidRect | null) =>
  a === b || (!!a && !!b && a.top === b.top && a.left === b.left && a.width === b.width && a.height === b.height);

export interface FluidHoverHighlightProps {
  /** The state from useFluidHover (or any { rect, glide, session }). */
  hover: Pick<FluidHoverState, "rect" | "glide" | "session">;
  /** Radius, fill, z-index. The container must be position: relative; the highlight is placed at its top-left corner. */
  className?: string;
  /** Extra attributes for styling, such as data-tone. */
  tone?: string;
}

/** The one highlight a fluid hover set renders: it springs between items on transforms, and fades in and out. */
export function FluidHoverHighlight({ hover, className, tone }: FluidHoverHighlightProps) {
  const reduced = useReducedMotion() ?? false;
  const { rect, glide, session } = hover;
  const place = rect ? { x: rect.left, y: rect.top, width: rect.width, height: rect.height } : undefined;
  return (
    <AnimatePresence initial={false}>
      {place ? (
        <motion.span key={session} className={className} data-tone={tone} aria-hidden="true"
          style={{ position: "absolute", top: 0, left: 0, pointerEvents: "none" }}
          initial={{ opacity: 0, ...place }}
          animate={{ opacity: 1, ...place }}
          exit={{ opacity: 0, transition: motionTokens.spring.fast.exit }}
          transition={{ default: glide && !reduced ? motionTokens.spring.fast : { duration: 0 }, opacity: { duration: motionTokens.duration.fast } }} />
      ) : null}
    </AnimatePresence>
  );
}

"use client";

/**
 * Lets an app swap the link and image elements Silicon UI components render.
 *
 * Without a provider, Silicon UI renders a plain `<a>` and `<img>`, so components work in any React app (Vite, Remix, Astro,
 * plain React). Wrap the app once to use your framework's or your own components instead:
 *
 *   import Link from "next/link";
 *   import Image from "next/image";
 *   import { SiliconProvider } from "@/components/silicon-ui/lib/silicon-provider";
 *
 *   <SiliconProvider link={Link} image={Image}>{children}</SiliconProvider>
 *
 * Any component that accepts these props works, such as a locale-aware Link from next-intl or a React Router Link
 * wrapped to map `href` to `to`.
 */
import { createContext, createElement, useContext, useMemo, type AnchorHTMLAttributes, type ComponentType, type ImgHTMLAttributes, type ReactNode, type Ref } from "react";

/** The props Silicon UI passes to a link: an href plus ordinary anchor attributes. */
export interface SiliconLinkProps extends AnchorHTMLAttributes<HTMLAnchorElement> {
  href: string;
  ref?: Ref<HTMLAnchorElement>;
}

/**
 * The props Silicon UI passes to an image. A subset of next/image's props, so next/image can be passed as is: either `fill`
 * (cover the positioned parent) or `width` and `height`, plus `sizes` and `priority` as hints.
 */
export interface SiliconImageProps extends Omit<ImgHTMLAttributes<HTMLImageElement>, "src" | "alt" | "width" | "height" | "loading" | "srcSet"> {
  src: string;
  alt: string;
  width?: number;
  height?: number;
  /** Fills the nearest positioned parent, like next/image's `fill`. */
  fill?: boolean;
  /** Loads the image eagerly with high priority, like next/image's `priority`. */
  priority?: boolean;
  loading?: "eager" | "lazy";
  ref?: Ref<HTMLImageElement>;
}

export type SiliconLinkComponent = ComponentType<SiliconLinkProps>;
export type SiliconImageComponent = ComponentType<SiliconImageProps>;

/** The default link: a plain anchor. */
export function SiliconAnchor(props: SiliconLinkProps) {
  return <a {...props} />;
}

const fillStyle = { position: "absolute", inset: 0, width: "100%", height: "100%" } as const;

/** The default image: a plain, lazily decoded `<img>` that understands `fill` and `priority`. */
export function SiliconImg({ alt, fill, priority, loading, style, ...props }: SiliconImageProps) {
  // eslint-disable-next-line @next/next/no-img-element -- the framework-free default; pass next/image through SiliconProvider instead.
  return <img alt={alt} decoding="async" {...props} loading={loading ?? (priority ? "eager" : "lazy")} fetchPriority={priority ? "high" : props.fetchPriority} style={fill ? { ...fillStyle, ...style } : style} />;
}

interface SiliconComponents {
  link: SiliconLinkComponent;
  image: SiliconImageComponent;
}

const SiliconContext = createContext<SiliconComponents>({ link: SiliconAnchor, image: SiliconImg });

export interface SiliconProviderProps {
  /** The link component Silicon UI renders for navigation, such as next/link or your own wrapped Link. Defaults to `<a>`. */
  link?: SiliconLinkComponent;
  /** The image component Silicon UI renders for photos, such as next/image. Defaults to `<img>`. */
  image?: SiliconImageComponent;
  children: ReactNode;
}

/** Sets the link and image components for every Silicon UI component inside it. Nested providers inherit what they do not set. */
export function SiliconProvider({ link, image, children }: SiliconProviderProps) {
  const parent = useContext(SiliconContext);
  const value = useMemo(() => ({ link: link ?? parent.link, image: image ?? parent.image }), [link, image, parent]);
  return <SiliconContext.Provider value={value}>{children}</SiliconContext.Provider>;
}

/** The link component from the nearest SiliconProvider, or a plain anchor. */
export const useArcLink = () => useContext(SiliconContext).link;
/** The image component from the nearest SiliconProvider, or a plain img. */
export const useArcImage = () => useContext(SiliconContext).image;

/** What Silicon UI components render for a link: the provider's link component, or a plain anchor. */
export function SiliconLink(props: SiliconLinkProps) {
  return createElement(useArcLink(), props);
}

/** What Silicon UI components render for an image: the provider's image component, or a plain img. */
export function SiliconImage(props: SiliconImageProps) {
  return createElement(useArcImage(), props);
}
